using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;
using Yato.UI;

namespace Yato.Editor
{
    /// <summary>
    /// 页面代码生成（T-P4-02）：从选中的预制体生成 View / Mediator / Proxy / 绑定分片。
    /// 已存在的文件不覆盖（保护手写区）；生成物带 auto-generated 头。
    /// </summary>
    public static class PageCodeGenerator
    {
        private const string Header =
            "// <auto-generated>\n" +
            "//     由 Yato.Editor/PageCodeGenerator 生成，重新生成不会覆盖已存在的文件。\n" +
            "// </auto-generated>\n";

        [MenuItem("Yato/CodeGen/Generate Page Code (Selection)", false, 302)]
        public static void GenerateForSelection()
        {
            var prefab = Selection.activeObject as GameObject;
            if (prefab == null)
            {
                Debug.LogWarning("[Yato.CodeGen] 请在 Project 面板选中一个预制体");
                return;
            }

            string path = AssetDatabase.GetAssetPath(prefab);
            if (string.IsNullOrEmpty(path))
            {
                Debug.LogWarning("[Yato.CodeGen] 选中的对象不是资源预制体");
                return;
            }

            Generate(path, prefab);
        }

        /// <summary>生成页面代码，返回新建的文件数。</summary>
        public static int Generate(string prefabPath, GameObject prefab)
        {
            string pageId = Path.GetFileNameWithoutExtension(prefabPath);
            string folder = Path.Combine(CodeGenSettings.EnsureOutputFolder(), pageId);
            if (!Directory.Exists(folder))
            {
                Directory.CreateDirectory(folder);
            }

            string ns = "Yato.Game.UI";
            var bindings = ComponentBinderValidator.CollectBindings(prefab);

            int created = 0;
            created += CreateFile(Path.Combine(folder, pageId + "PageView.cs"), BuildView(pageId, ns));
            created += CreateFile(Path.Combine(folder, pageId + "Mediator.cs"), BuildMediator(pageId, ns));
            created += CreateFile(Path.Combine(folder, pageId + "Proxy.cs"), BuildProxy(pageId, ns));
            created += CreateFile(Path.Combine(folder, pageId + "PageView.Bindings.cs"), BuildBindings(pageId, ns, bindings));

            AssetDatabase.Refresh();
            Debug.Log(string.Format("[Yato.CodeGen] {0}：新建 {1} 个文件（已存在的已跳过）→ {2}", pageId, created, folder));
            return created;
        }

        private static string BuildView(string pageId, string ns)
        {
            var builder = new StringBuilder();
            builder.Append(Header);
            builder.Append("using UnityEngine;\nusing Yato.UI;\n\n");
            builder.Append("namespace ").Append(ns).Append("\n{\n");
            builder.Append("    public partial class ").Append(pageId).Append("PageView : UIPageView\n    {\n");
            builder.Append("        protected override void Awake()\n        {\n");
            builder.Append("            base.Awake();\n            BindComponents();\n        }\n\n");
            builder.Append("        public override void OnOpen(object args)\n        {\n        }\n\n");
            builder.Append("        public override void OnClose(bool destroy)\n        {\n        }\n");
            builder.Append("    }\n}\n");
            return builder.ToString();
        }

        private static string BuildMediator(string pageId, string ns)
        {
            var builder = new StringBuilder();
            builder.Append(Header);
            builder.Append("using Yato.UI;\n\n");
            builder.Append("namespace ").Append(ns).Append("\n{\n");
            builder.Append("    public class ").Append(pageId).Append("Mediator : UIPageMediator<")
                .Append(pageId).Append("PageView>\n    {\n");
            builder.Append("        public ").Append(pageId).Append("Mediator()\n        {\n        }\n\n");
            builder.Append("        public ").Append(pageId)
                .Append("Mediator(string mediatorName) : base(mediatorName)\n        {\n        }\n\n");
            builder.Append("        protected override UIPageProxy CreateProxy()\n        {\n");
            builder.Append("            return new ").Append(pageId).Append("Proxy(Context.InstanceName + \"Proxy\");\n");
            builder.Append("        }\n");
            builder.Append("    }\n}\n");
            return builder.ToString();
        }

        private static string BuildProxy(string pageId, string ns)
        {
            var builder = new StringBuilder();
            builder.Append(Header);
            builder.Append("using Yato.UI;\n\n");
            builder.Append("namespace ").Append(ns).Append("\n{\n");
            builder.Append("    public class ").Append(pageId).Append("Proxy : UIPageProxy\n    {\n");
            builder.Append("        public ").Append(pageId)
                .Append("Proxy(string proxyName) : base(proxyName)\n        {\n        }\n\n");
            builder.Append("        public override void RefreshView()\n        {\n        }\n");
            builder.Append("    }\n}\n");
            return builder.ToString();
        }

        private static string BuildBindings(string pageId, string ns, Dictionary<string, Component> bindings)
        {
            var builder = new StringBuilder();
            builder.Append(Header);
            builder.Append("using UnityEngine;\nusing Yato.UI;\n\n");
            builder.Append("namespace ").Append(ns).Append("\n{\n");
            builder.Append("    public partial class ").Append(pageId).Append("PageView\n    {\n");
            builder.Append("        private ComponentBinder m_binder;\n\n");
            builder.Append("        protected ComponentBinder Binder\n        {\n");
            builder.Append("            get\n            {\n");
            builder.Append("                if (m_binder == null)\n                {\n");
            builder.Append("                    m_binder = GetComponent<ComponentBinder>();\n");
            builder.Append("                }\n\n                return m_binder;\n            }\n        }\n\n");
            builder.Append("        private void BindComponents()\n        {\n");

            if (bindings == null || bindings.Count == 0)
            {
                builder.Append("            // TODO：在预制体上挂 ComponentBinder 并添加绑定后重新生成\n");
            }
            else
            {
                foreach (KeyValuePair<string, Component> pair in bindings)
                {
                    if (pair.Value == null)
                    {
                        continue;
                    }

                    builder.Append("            // ").Append(pair.Key).Append("\n");
                }
            }

            builder.Append("        }\n    }\n}\n");
            return builder.ToString();
        }

        private static int CreateFile(string path, string content)
        {
            if (File.Exists(path))
            {
                return 0;
            }

            File.WriteAllText(path, content, new UTF8Encoding(false));
            return 1;
        }
    }
}
